def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(row.count(c) for row in grid))
    sep = next(c for c in range(w) if all(grid[r][c] == 2 for r in range(h)))

    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != 2]
    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        out[r][sep] = 2

    if cells:
        min_c = min(c for _, c, _ in cells)
        max_c = max(c for _, c, _ in cells)
        shift = sep + 1 - min_c
        for r, c, color in cells:
            nc = c + shift
            if 0 <= nc < w:
                out[r][nc] = color
        stripe = sep + 1 + (max_c - min_c + 1)
        if stripe < w:
            for r in range(h):
                out[r][stripe] = 8
    return out
